// Pad each division to 12 with placeholder teams
function buildInitialTeams() {
  const teams = {};
  for (const div of DIVISIONS) {
    const real = REAL_TEAMS[div.id] || [];
    const padded = [...real];
    let i = padded.length + 1;
    while (padded.length < TEAMS_PER_DIVISION) {
      padded.push({
        p1: `TBC Player ${i * 2 - 1}`,
        p2: `TBC Player ${i * 2}`,
        r1: null,
        r2: null,
        placeholder: true,
      });
      i++;
    }
    teams[div.id] = padded.map((t, idx) => ({
      ...t,
      id: `${div.id}-t${idx + 1}`,
      seed: idx + 1,
      divisionId: div.id,
    }));
  }
  return teams;
}

// ---------------------------------------------------------------------------
// ROUND-ROBIN FIXTURE GENERATION (Circle method)
// ---------------------------------------------------------------------------
function generateRoundRobin(teamIds) {
  const n = teamIds.length;
  const ids = [...teamIds];
  const rounds = [];
  for (let r = 0; r < n - 1; r++) {
    const round = [];
    for (let i = 0; i < n / 2; i++) {
      const a = ids[i];
      const b = ids[n - 1 - i];
      // Alternate home/away for visual variety
      if (r % 2 === 0) round.push([a, b]);
      else round.push([b, a]);
    }
    rounds.push(round);
    // Rotate: keep first fixed, cycle the rest
    const fixed = ids[0];
    const rest = ids.slice(1);
    rest.unshift(rest.pop());
    ids.splice(0, ids.length, fixed, ...rest);
  }
  return rounds;
}

function buildInitialFixtures(teams) {
  const fixtures = [];
  let fid = 1;
  for (const div of DIVISIONS) {
    const divTeams = teams[div.id];
    const placeholderIds = new Set(divTeams.filter((t) => t.placeholder).map((t) => t.id));
    const rounds = generateRoundRobin(divTeams.map((t) => t.id));

    // Reorder rounds so unconfirmed fixtures sink to the end. We push rounds
    // containing TBC-vs-TBC ("dead") games last, then rounds with TBC-vs-real
    // ("mixed") games, so the earliest rounds are the most playable. This means
    // every real team gets a fixture in week 1 (real opponent where possible,
    // otherwise a slot that confirms once the league fills).
    const scored = rounds.map((round, origIdx) => {
      let dead = 0,
        mixed = 0;
      for (const [a, b] of round) {
        const aPh = placeholderIds.has(a);
        const bPh = placeholderIds.has(b);
        if (aPh && bPh) dead++;
        else if (aPh || bPh) mixed++;
      }
      return { round, dead, mixed, origIdx };
    });
    scored.sort(
      (x, y) => x.dead - y.dead || x.mixed - y.mixed || x.origIdx - y.origIdx
    );

    scored.forEach((entry, rIdx) => {
      entry.round.forEach(([t1, t2]) => {
        const bothTbc = placeholderIds.has(t1) && placeholderIds.has(t2);
        const oneTbc = placeholderIds.has(t1) || placeholderIds.has(t2);
        fixtures.push({
          id: `F${String(fid++).padStart(4, "0")}`,
          divisionId: div.id,
          round: rIdx + 1,
          team1Id: t1,
          team2Id: t2,
          status: "pending", // pending | completed | walkover
          sets: null, // [[g1, g2], [g1, g2], [g1, g2]?]
          enteredAt: null,
          enteredBy: null,
          notes: "",
          tbc: bothTbc ? "both" : oneTbc ? "one" : null, // marks unconfirmed fixtures
        });
      });
    });
  }
  return fixtures;
}

// ---------------------------------------------------------------------------
// DATE HELPERS
// ---------------------------------------------------------------------------
function weekRangeForRound(round) {
  // Round n starts the Saturday of week n (round 1 = Jun 6)
  const start = new Date(LEAGUE_START);
  start.setDate(start.getDate() + (round - 1) * 7);
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  return { start, end };
}

function fmtDate(d, opts = {}) {
  const { short = false, day = false } = opts;
  if (short) return d.toLocaleDateString("en-IE", { day: "numeric", month: "short" });
  if (day) return d.toLocaleDateString("en-IE", { weekday: "short", day: "numeric", month: "short" });
  return d.toLocaleDateString("en-IE", { day: "numeric", month: "long", year: "numeric" });
}

function currentRound() {
  const now = new Date();
  if (now < LEAGUE_START) return 0; // pre-season
  const diff = Math.floor((now - LEAGUE_START) / (1000 * 60 * 60 * 24 * 7));
  return Math.min(diff + 1, ROUNDS);
}

function daysUntilDeadline() {
  const now = new Date();
  const diff = Math.ceil((LEAGUE_DEADLINE - now) / (1000 * 60 * 60 * 24));
  return diff;
}

// Time-to-start (used by countdown banner & live panel)
function timeUntilStart() {
  const now = new Date();
  const ms = LEAGUE_START.getTime() - now.getTime();
  if (ms <= 0) return null;
  const days = Math.floor(ms / 86400000);
  const hours = Math.floor((ms % 86400000) / 3600000);
  const mins = Math.floor((ms % 3600000) / 60000);
  const secs = Math.floor((ms % 60000) / 1000);
  return { days, hours, mins, secs, totalMs: ms };
}

function Countdown({ size = "md", showSeconds = true }) {
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, []);
  const t = timeUntilStart();
  if (!t) return null;
  const big = size === "lg" ? 96 : size === "md" ? 48 : 30;
  const lbl = size === "lg" ? 13 : size === "md" ? 10 : 9;
  const gap = size === "lg" ? 28 : 14;
  const units = [
    { v: t.days, l: "DAYS" },
    { v: t.hours, l: "HOURS" },
    { v: t.mins, l: "MINS" },
  ];
  if (showSeconds) units.push({ v: t.secs, l: "SECS" });
  return (
    <div style={{ display: "flex", gap, alignItems: "flex-end", fontFamily: F.display }}>
      {units.map((u, i) => (
        <div key={i} style={{ textAlign: "center" }}>
          <div
            style={{
              fontSize: big,
              lineHeight: 0.9,
              color: C.accent,
              fontVariantNumeric: "tabular-nums",
              letterSpacing: "-0.02em",
            }}
          >
            {String(u.v).padStart(2, "0")}
          </div>
          <div
            style={{
              fontSize: lbl,
              color: C.mute,
              fontFamily: F.body,
              fontWeight: 600,
              letterSpacing: "0.15em",
              marginTop: 4,
            }}
          >
            {u.l}
          </div>
        </div>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// STANDINGS COMPUTATION
// Win = 3 pts | Straight-sets bonus = +1 pt
// Tiebreak: Points → H2H → Set diff → Game diff
// ---------------------------------------------------------------------------
function computeStandings(divisionId, teams, fixtures) {
  const divTeams = teams[divisionId];
  const rows = divTeams.map((t) => ({
    teamId: t.id,
    team: t,
    P: 0,
    W: 0,
    L: 0,
    Pts: 0,
    Bonus: 0,
    SF: 0,
    SA: 0,
    GF: 0,
    GA: 0,
    h2h: {}, // opponentId -> {won, lost}
  }));
  const byId = Object.fromEntries(rows.map((r) => [r.teamId, r]));

  fixtures
    .filter((f) => f.divisionId === divisionId && f.status === "completed" && f.sets)
    .forEach((f) => {
      const r1 = byId[f.team1Id];
      const r2 = byId[f.team2Id];
      if (!r1 || !r2) return;
      let s1 = 0,
        s2 = 0,
        g1 = 0,
        g2 = 0;
      for (const [a, b] of f.sets) {
        g1 += a;
        g2 += b;
        if (a > b) s1++;
        else if (b > a) s2++;
      }
      r1.P++;
      r2.P++;
      r1.SF += s1;
      r1.SA += s2;
      r2.SF += s2;
      r2.SA += s1;
      r1.GF += g1;
      r1.GA += g2;
      r2.GF += g2;
      r2.GA += g1;
      const t1Won = s1 > s2;
      const winner = t1Won ? r1 : r2;
      const loser = t1Won ? r2 : r1;
      winner.W++;
      loser.L++;
      winner.Pts += 3;
      const straight = (t1Won && s2 === 0) || (!t1Won && s1 === 0);
      if (straight) {
        winner.Pts += 1;
        winner.Bonus++;
      }
      winner.h2h[loser.teamId] = (winner.h2h[loser.teamId] || 0) + 1;
    });

  rows.sort((a, b) => {
    if (b.Pts !== a.Pts) return b.Pts - a.Pts;
    const aWins = a.h2h[b.teamId] || 0;
    const bWins = b.h2h[a.teamId] || 0;
    if (aWins !== bWins) return bWins - aWins;
    const sdA = a.SF - a.SA;
    const sdB = b.SF - b.SA;
    if (sdB !== sdA) return sdB - sdA;
    return b.GF - b.GA - (a.GF - a.GA);
  });

  rows.forEach((r, i) => (r.rank = i + 1));
  return rows;
}

// ---------------------------------------------------------------------------
// PERSISTENT STORAGE
// ---------------------------------------------------------------------------
async function loadState() {
  try {
    if (typeof window === "undefined" || !window.storage) return null;
    const result = await window.storage.get(STORAGE_KEY, true);
    if (!result || !result.value) return null;
    return JSON.parse(result.value);
  } catch (e) {
    return null;
  }
}

async function saveState(state) {
  try {
    if (typeof window === "undefined" || !window.storage) return false;
    await window.storage.set(STORAGE_KEY, JSON.stringify(state), true);
    return true;
  } catch (e) {
    console.warn("Save failed:", e);
    return false;
  }
}

