export default function W7LeagueTracker() {
  const [mode, setMode] = useState("team");
  const [teams, setTeams] = useState(() => buildInitialTeams());
  const [fixtures, setFixtures] = useState(() => buildInitialFixtures(buildInitialTeams()));
  const [settings, setSettings] = useState({
    adminPin: DEFAULT_ADMIN_PIN,
    lowerStatus: "full", // "full" | "available"
    upperStatus: "available",
  });
  const [isAdmin, setIsAdmin] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState("");

  // Load from persistent storage on mount
  useEffect(() => {
    (async () => {
      const stored = await loadState();
      if (stored) {
        if (stored.teams) setTeams(stored.teams);
        if (stored.fixtures) setFixtures(stored.fixtures);
        if (stored.settings)
          setSettings((prev) => ({ ...prev, ...stored.settings }));
      }
      setLoaded(true);
    })();
  }, []);

  // Save when state changes (after initial load)
  useEffect(() => {
    if (!loaded) return;
    const t = setTimeout(async () => {
      const ok = await saveState({ teams, fixtures, settings, lastUpdated: Date.now() });
      if (ok) {
        setSaveStatus("Saved");
        setTimeout(() => setSaveStatus(""), 1500);
      }
    }, 600);
    return () => clearTimeout(t);
  }, [teams, fixtures, settings, loaded]);

  const handleScore = useCallback((fixtureId, sets) => {
    setFixtures((prev) =>
      prev.map((f) =>
        f.id === fixtureId
          ? { ...f, sets, status: "completed", enteredAt: Date.now() }
          : f
      )
    );
  }, []);

  const handleClearScore = useCallback((fixtureId) => {
    setFixtures((prev) =>
      prev.map((f) =>
        f.id === fixtureId
          ? { ...f, sets: null, status: "pending", enteredAt: null }
          : f
      )
    );
  }, []);

  const handleResetAllScores = useCallback(() => {
    setFixtures((prev) =>
      prev.map((f) => ({ ...f, sets: null, status: "pending", enteredAt: null }))
    );
  }, []);

  if (!loaded) {
    return (
      <div style={{ background: C.bg, color: C.mute, minHeight: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", fontFamily: F.body, gap: 20 }}>
        <Logo size="md" style={{ width: 96, height: 96, opacity: 0.8 }} />
        <div>Loading league data…</div>
      </div>
    );
  }

  if (mode === "live") {
    return <LiveScreen teams={teams} fixtures={fixtures} settings={settings} onExit={() => setMode("team")} />;
  }

  return (
    <div style={{ background: C.bg, color: C.text, minHeight: "100vh", fontFamily: F.body }}>
      <TopBar mode={mode} setMode={setMode} isAdmin={isAdmin} onLogoutAdmin={() => setIsAdmin(false)} />
      {saveStatus && (
        <div
          style={{
            position: "fixed",
            bottom: 16,
            right: 16,
            background: C.accent,
            color: C.bg,
            padding: "6px 12px",
            borderRadius: 4,
            fontSize: 11,
            fontWeight: 700,
            letterSpacing: "0.05em",
            zIndex: 100,
          }}
        >
          ✓ {saveStatus}
        </div>
      )}
      {mode === "team" && <TeamView teams={teams} fixtures={fixtures} />}
      {mode === "status" && <StatusView settings={settings} />}
      {mode === "knockout" && <KnockoutView teams={teams} fixtures={fixtures} />}
      {mode === "admin" && (
        <AdminView
          teams={teams}
          fixtures={fixtures}
          onScore={handleScore}
          onClearScore={handleClearScore}
          onResetAllScores={handleResetAllScores}
          isAdmin={isAdmin}
          onUnlock={() => setIsAdmin(true)}
          settings={settings}
          onUpdateSettings={setSettings}
        />
      )}
      <div
        style={{
          padding: "28px 20px 32px",
          borderTop: `1px solid ${C.border}`,
          marginTop: 40,
        }}
      >
        <div style={{ maxWidth: 1100, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 14, flexWrap: "wrap" }}>
            <Logo size="sm" style={{ width: 36, height: 36 }} />
            <div style={{ fontFamily: F.display, fontSize: 16, color: C.text, letterSpacing: "0.04em" }}>
              GET IN TOUCH · BOOK A COURT
            </div>
          </div>
          <ContactBar />
          <div
            style={{
              marginTop: 14,
              fontSize: 12.5,
              color: C.mute,
              lineHeight: 1.7,
              textAlign: "center",
            }}
          >
            See all our competitions &amp; socials and book in here:{" "}
            <a
              href={CONTACT.playtomic}
              target="_blank"
              rel="noopener noreferrer"
              style={{ color: C.accent, textDecoration: "underline", wordBreak: "break-word" }}
            >
              playtomic.com/clubs/w7-padel-hub-wicklow
            </a>
            <br />
            <a href={`mailto:${CONTACT.email}`} style={{ color: C.accent, textDecoration: "underline" }}>
              {CONTACT.email}
            </a>
            &nbsp;·&nbsp;
            <a href={`tel:${CONTACT.phoneTel}`} style={{ color: C.accent, textDecoration: "underline" }}>
              {CONTACT.phoneDisplay}
            </a>
            &nbsp;·&nbsp;
            <a href={CONTACT.whatsapp} target="_blank" rel="noopener noreferrer" style={{ color: C.accent, textDecoration: "underline" }}>
              WhatsApp
            </a>
          </div>
          <div style={{ marginTop: 18, fontSize: 11, color: C.mute, textAlign: "center" }}>
            W7 Padel · Wicklow Town · Summer Leagues 2026 · Tracker {VERSION} · Built {BUILD_DATE}
          </div>
        </div>
      </div>
    </div>
  );
}
